function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must be lists of the same length.';
  if (operations[0] !== 'VideoSharingPlatform' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with VideoSharingPlatform and no arguments.';
  if (operations.length - 1 > 100000) return 'At most 10^5 calls in total.';
  const isId = v => Number.isInteger(v) && v >= 0 && v <= 100000;
  const lengths = new Map();
  const free = [];
  let next = 0, uploaded = 0, watched = 0;
  for (let i = 1; i < operations.length; i++) {
    const op = operations[i], call = args[i];
    if (!Array.isArray(call)) return 'Every call needs a list of arguments.';
    if (op === 'upload') {
      const video = call[0];
      if (call.length !== 1 || typeof video !== 'string' || !/^[0-9]+$/.test(video)) return 'upload needs a non-empty string of digits.';
      uploaded += video.length;
      if (uploaded > 100000) return 'The uploaded videos have at most 10^5 digits in total.';
      lengths.set(free.length ? free.shift() : next++, video.length);
    } else if (op === 'watch') {
      const [videoId, startMinute, endMinute] = call;
      if (call.length !== 3 || !isId(videoId)) return 'watch needs a videoId from 0 to 10^5, startMinute and endMinute.';
      if (!Number.isInteger(startMinute) || !Number.isInteger(endMinute) || startMinute < 0 || startMinute >= endMinute || endMinute >= 100000) return 'Minutes need 0 <= startMinute < endMinute < 10^5.';
      if (lengths.has(videoId) && startMinute >= lengths.get(videoId)) return 'startMinute must be a minute of the watched video.';
      watched += endMinute - startMinute;
      if (watched > 100000) return 'The watched spans add up to at most 10^5 minutes.';
    } else if (['remove', 'like', 'dislike', 'getLikesAndDislikes', 'getViews'].includes(op)) {
      if (call.length !== 1 || !isId(call[0])) return op + ' needs a videoId from 0 to 10^5.';
      if (op === 'remove' && lengths.delete(call[0])) {
        let low = 0, high = free.length;
        while (low < high) { const mid = (low + high) >> 1; if (free[mid] < call[0]) low = mid + 1; else high = mid; }
        free.splice(low, 0, call[0]);
      }
    } else return 'Unknown operation ' + op + '.';
  }
  return null;
}

