class VideoSharingPlatform {
  constructor() {
    this.videos = new Map();
    this.nextId = 0;
    this.freeIds = [];
  }

  upload(video) {
    const videoId = this.freeIds.length > 0 ? this.takeSmallestFreeId() : this.nextId++;
    this.videos.set(videoId, { content: video, views: 0, likes: 0, dislikes: 0 });
    return videoId;
  }

  remove(videoId) {
    if (this.videos.delete(videoId)) {
      this.addFreeId(videoId);
    }
  }

  watch(videoId, startMinute, endMinute) {
    const entry = this.videos.get(videoId);
    if (entry === undefined) {
      return "-1";
    }
    entry.views++;
    const lastMinute = Math.min(endMinute, entry.content.length - 1);
    return entry.content.slice(startMinute, lastMinute + 1);
  }

  like(videoId) {
    const entry = this.videos.get(videoId);
    if (entry !== undefined) {
      entry.likes++;
    }
  }

  dislike(videoId) {
    const entry = this.videos.get(videoId);
    if (entry !== undefined) {
      entry.dislikes++;
    }
  }

  getLikesAndDislikes(videoId) {
    const entry = this.videos.get(videoId);
    return entry === undefined ? [-1] : [entry.likes, entry.dislikes];
  }

  getViews(videoId) {
    const entry = this.videos.get(videoId);
    return entry === undefined ? -1 : entry.views;
  }

  addFreeId(id) {
    const heap = this.freeIds;
    heap.push(id);
    let index = heap.length - 1;
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (heap[parent] <= heap[index]) break;
      [heap[parent], heap[index]] = [heap[index], heap[parent]];
      index = parent;
    }
  }

  takeSmallestFreeId() {
    const heap = this.freeIds;
    const smallest = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return smallest;
    heap[0] = last;
    let index = 0;
    for (;;) {
      const left = 2 * index + 1;
      const right = left + 1;
      let child = index;
      if (left < heap.length && heap[left] < heap[child]) child = left;
      if (right < heap.length && heap[right] < heap[child]) child = right;
      if (child === index) return smallest;
      [heap[child], heap[index]] = [heap[index], heap[child]];
      index = child;
    }
  }
}

