class VideoSharingPlatform {
  // slots[id] holds the hosted video or nothing; upload scans for the first empty slot.
  constructor() {
    this.slots = [];
  }
  upload(video) {
    let id = 0;
    while (this.slots[id]) id++;
    this.slots[id] = { video, views: 0, likes: 0, dislikes: 0 };
    return id;
  }
  remove(videoId) {
    this.slots[videoId] = null;
  }
  watch(videoId, startMinute, endMinute) {
    const slot = this.slots[videoId];
    if (!slot) return '-1';
    slot.views += 1;
    let out = '';
    for (let minute = startMinute; minute <= endMinute && minute < slot.video.length; minute++) out += slot.video[minute];
    return out;
  }
  like(videoId) {
    if (this.slots[videoId]) this.slots[videoId].likes += 1;
  }
  dislike(videoId) {
    if (this.slots[videoId]) this.slots[videoId].dislikes += 1;
  }
  getLikesAndDislikes(videoId) {
    const slot = this.slots[videoId];
    return slot ? [slot.likes, slot.dislikes] : [-1];
  }
  getViews(videoId) {
    const slot = this.slots[videoId];
    return slot ? slot.views : -1;
  }
}

