function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const calls = large ? 499 : 1 + pick(12);
  const operations = ['VideoSharingPlatform'];
  const args = [[]];
  const lengths = new Map();
  let next = 0;
  const digits = () => {
    const n = 1 + pick(large ? 40 : 4);
    let video = '';
    for (let k = 0; k < n; k++) video += String(pick(10));
    return video;
  };
  // Mostly hosted ids, sometimes ids that are free or were never used.
  const someId = () => {
    const roll = rand();
    if (lengths.size && roll < 0.7) return [...lengths.keys()][pick(lengths.size)];
    if (roll < 0.9) return pick(next + 2);
    return large ? pick(100001) : pick(6);
  };
  for (let c = 0; c < calls; c++) {
    const roll = rand();
    if (roll < 0.3) {
      const video = digits();
      let id = 0;
      while (lengths.has(id)) id++;
      lengths.set(id, video.length);
      next = Math.max(next, id + 1);
      operations.push('upload');
      args.push([video]);
    } else if (roll < 0.42) {
      const id = someId();
      lengths.delete(id);
      operations.push('remove');
      args.push([id]);
    } else if (roll < 0.65) {
      const id = someId();
      const length = lengths.has(id) ? lengths.get(id) : 1 + pick(5);
      const start = pick(length);
      const end = start + 1 + pick(length + 2);
      operations.push('watch');
      args.push([id, start, end]);
    } else {
      const op = ['like', 'dislike', 'like', 'dislike', 'getLikesAndDislikes', 'getViews'][pick(6)];
      operations.push(op);
      args.push([someId()]);
    }
  }
  return [operations, args];
}
